#include <cuchar>
#include <cwchar>
#include <cassert>
#include <type_traits>
#include <utility>
#include <climits>
int main() {
    std::mbstate_t state{};
    char8_t character{};
    assert(std::mbrtoc8(&character, "A", 1, &state) == 1);
    assert(character == u8'A');
    char bytes[MB_LEN_MAX]{};
    assert(std::c8rtomb(bytes, character, &state) == 1);
    assert(bytes[0] == 'A');
}
